using System;using System.Linq;using System.Threading;using System.Windows;using System.Windows.Controls;
namespace FoolLauncher {
 public static class LoaderSelectionDialog {
  public static bool Show(Window owner,string minecraft,out LoaderSelection selection){LoaderSelection picked=null;bool accepted=false,loading=false;CancellationTokenSource cancel=null;var catalog=new LoaderCatalog();var d=new ThemedDialog(owner,"选择模组加载器","Minecraft "+minecraft+" · 可保留纯原版，或一起安装一个兼容的加载器。");var type=new ComboBox{Padding=new Thickness(9,6,9,6),Foreground=System.Windows.Media.Brushes.Black,Margin=new Thickness(0,6,0,16)};foreach(var key in new[]{"","forge","neoforge","fabric-loader","quilt-loader"})type.Items.Add(new ComboBoxItem{Content=key==""?"不安装加载器（纯原版）":new LoaderSelection{Key=key}.Name,Tag=key});type.SelectedIndex=0;d.Body.Children.Add(ThemedDialog.Text("加载器"));d.Body.Children.Add(type);d.Body.Children.Add(ThemedDialog.Text("兼容版本"));var versions=new ComboBox{Padding=new Thickness(9,6,9,6),Foreground=System.Windows.Media.Brushes.Black,MaxDropDownHeight=260,IsEnabled=false,Margin=new Thickness(0,6,0,14)};d.Body.Children.Add(versions);var status=ThemedDialog.Text("仅安装原版 Minecraft。之后仍可创建带加载器的独立实例。");status.SetResourceReference(TextBlock.ForegroundProperty,"Brush.Muted");d.Body.Children.Add(status);var confirm=d.Button("开始安装",()=>{if(loading)return;string key=Convert.ToString(((ComboBoxItem)type.SelectedItem).Tag);picked=key==""?null:versions.SelectedItem as LoaderSelection;if(key!=""&&picked==null)return;accepted=true;d.Window.Close();},true);var retry=d.Button("重新查询",()=>{},false);retry.Visibility=Visibility.Collapsed;d.Buttons.Children.Add(retry);d.Buttons.Children.Add(d.Button("取消",()=>d.Window.Close(),false));d.Buttons.Children.Add(confirm);
   Func<System.Threading.Tasks.Task> query=async()=>{if(cancel!=null)cancel.Cancel();cancel=new CancellationTokenSource();var ct=cancel.Token;string key=Convert.ToString(((ComboBoxItem)type.SelectedItem).Tag);versions.ItemsSource=null;versions.IsEnabled=false;retry.Visibility=Visibility.Collapsed;if(key==""){loading=false;confirm.IsEnabled=true;status.Text="仅安装原版 Minecraft。";return;}loading=true;confirm.IsEnabled=false;status.Text="正在查询 Minecraft "+minecraft+" 的 "+new LoaderSelection{Key=key}.Name+" 版本…";try{var list=await catalog.Versions(key,minecraft,ct);if(ct.IsCancellationRequested)return;versions.ItemsSource=list;versions.SelectedIndex=list.Length>0?0:-1;versions.IsEnabled=list.Length>0;status.Text=list.Length>0?"找到 "+list.Length+" 个兼容版本。游戏本体、加载器及其依赖将一起下载。":"此游戏版本没有可用的加载器版本，请选择其他加载器或纯原版。";confirm.IsEnabled=list.Length>0;}catch(OperationCanceledException){if(!ct.IsCancellationRequested){status.Text="查询超时，请重试。";retry.Visibility=Visibility.Visible;}}catch(Exception ex){if(!ct.IsCancellationRequested){status.Text="查询失败："+ex.Message;retry.Visibility=Visibility.Visible;}}finally{if(!ct.IsCancellationRequested)loading=false;}};type.SelectionChanged+=async(s,e)=>await query();retry.Click+=async(s,e)=>await query();d.Window.Closed+=(s,e)=>{if(cancel!=null)cancel.Cancel();};d.Window.ShowDialog();selection=picked;return accepted;}
 }
}
